-- Gegenereerd door scripts/build-seed-sql.mjs uit docs/seed-data.json. Niet met de hand aanpassen.
-- Bron: vvpeursum.nl teampagina (stand, selectie) + voetbal.nl app (programma, uitslagen), peildatum 2026-10-10
begin;


with s as (insert into standings_snapshots (opgehaald_op, bron) values ('2026-10-10 18:00+02', 'seed') returning id)
select s.id, t.id, v.positie, v.gespeeld, v.winst, v.gelijk, v.verlies, v.voor, v.tegen, v.punten
from s, (values
  ('Peursum 4', 1, 4, 4, 0, 0, 15, 1, 12),
  ('Arkel 4', 2, 4, 4, 0, 0, 15, 7, 12),
  ('Vuren 3', 3, 4, 2, 1, 1, 11, 6, 7),
  ('SteDoCo 4', 4, 3, 2, 0, 1, 12, 8, 6),
  ('Asperen 5', 5, 4, 2, 0, 2, 7, 11, 6),
  ('Leerdam Sport''55 5', 6, 3, 1, 1, 1, 5, 2, 4),
  ('VVAC 6', 7, 2, 1, 0, 1, 12, 3, 3),
  ('Ameide 4', 8, 3, 1, 0, 2, 3, 9, 3),
  ('GJS 5', 9, 4, 1, 0, 3, 11, 13, 3),
  ('Hardinxveld 5', 10, 2, 0, 1, 1, 1, 7, 1),
  ('SVS''65 3', 11, 4, 0, 1, 3, 3, 10, 1),
  ('SV Noordeloos 3', 12, 3, 0, 0, 3, 1, 19, 0)
) as v (team, positie, gespeeld, winst, gelijk, verlies, voor, tegen, punten)
join teams t on t.naam = v.team;



commit;
